  }
}

function resolveIndexRootDir(value: string | undefined): string {
  if (value === undefined) {
    return DEFAULT_INDEX_ROOT_DIR;
  }

  const trimmedValue = value.trim();
  if (trimmedValue.length === 0) {
    return DEFAULT_INDEX_ROOT_DIR;
  }

  return path.resolve(trimmedValue);
