import { ContextSnippetSchema, type ContextSnippet } from "./contextTypes.js";

interface CreateContextSnippetInput {
  source: string;
  startOffset: number;
  endOffset: number;
  maxLength?: number;
}

export function createContextSnippet(input: CreateContextSnippetInput): ContextSnippet {
  const maxLength = input.maxLength ?? 160;
  const padding = Math.max(24, Math.floor(maxLength / 2));
  const rawStart = Math.max(0, input.startOffset - padding);
  const rawEnd = Math.min(input.source.length, input.endOffset + padding);
  const rawSnippet = input.source.slice(rawStart, rawEnd).trim().replace(/\s+/g, " ");

  if (rawSnippet.length <= maxLength) {
    return ContextSnippetSchema.parse({
      text: rawSnippet,
      truncated: false,
    });
  }

  const centeredStart = Math.max(0, Math.floor((rawSnippet.length - maxLength) / 2));
  const truncatedText = `${rawSnippet.slice(centeredStart, centeredStart + maxLength - 3).trim()}...`;

  return ContextSnippetSchema.parse({
    text: truncatedText,
    truncated: true,
  });
}

import { z } from "zod";
import { SourceRangeSchema } from "../diagnostics/diagnosticFactory.js";

export const EnclosingContextKindSchema = z.enum(["class", "function", "interface", "method"]);

export const EnclosingContextSchema = z.object({
  name: z.string().nullable(),
  kind: EnclosingContextKindSchema,
  range: SourceRangeSchema,
});

export const ContextSnippetSchema = z.object({
  text: z.string(),
  truncated: z.boolean(),
});

export type EnclosingContext = z.infer<typeof EnclosingContextSchema>;
export type ContextSnippet = z.infer<typeof ContextSnippetSchema>;

import Parser from "tree-sitter";
import { createSourceRange } from "../diagnostics/diagnosticFactory.js";
import { EnclosingContextSchema, type EnclosingContext } from "./contextTypes.js";

interface ExtractEnclosingContextInput {
  tree: Parser.Tree;
  startOffset: number;
  endOffset: number;
}

export function extractEnclosingContext(input: ExtractEnclosingContextInput): EnclosingContext | null {
  let current: Parser.SyntaxNode | null = input.tree.rootNode.descendantForIndex(input.startOffset, input.endOffset);

  while (current) {
    const contextKind = getEnclosingContextKind(current);
    if (contextKind) {
      return EnclosingContextSchema.parse({
        name: current.childForFieldName("name")?.text ?? null,
        kind: contextKind,
        range: createSourceRange(
          current.startPosition,
          current.endPosition,
          current.startIndex,
          current.endIndex,
        ),
      });
    }

    current = current.parent;
  }

  return null;
}

function getEnclosingContextKind(node: Parser.SyntaxNode): EnclosingContext["kind"] | null {
  switch (node.type) {
    case "class_declaration":
    case "class_definition":
      return "class";

  }

  return null;
}

function getEnclosingContextKind(node: Parser.SyntaxNode): EnclosingContext["kind"] | null {
  switch (node.type) {
    case "class_declaration":
    case "class_definition":
      return "class";
    case "function_declaration":
    case "function_definition":
    case "variable_declarator":
      return "function";
    case "interface_declaration":
      return "interface";
    case "method_definition":
      return "method";
    default:
      return null;
  }
}

