function findFirstErrorNode(node: Parser.SyntaxNode): Parser.SyntaxNode | null {
  if (node.isError || node.isMissing) {
    return node;
  }

  for (const child of node.children) {
    const errorNode = findFirstErrorNode(child);
    if (errorNode) {
      return errorNode;
    }
  }

  return null;
}

