export function getCompiledQuery(language: RegisteredLanguage, definition: CompilableQueryDefinition): Parser.Query {
  const cacheKey = `${language.id}:${definition.source}`;
  const cachedQuery = queryCache.get(cacheKey);
  if (cachedQuery) {
